  {
    SELECT ?investor
    WHERE {
      ?holding ex:hasInvestor ?investor .
      ?holding ex:taxesPaid ?taxesPaid .
    }
    GROUP BY ?investor
    HAVING (SUM(xsd:decimal(?taxesPaid)) > 500000)
  }
}

