WHERE {
  ?event a ex:ScenarioRebalancing ;
         ex:currentAllocationPct ?currentAllocationPct ;
         ex:newAllocationPct ?newAllocationPct .
  BIND(IF(xsd:decimal(?newAllocationPct) > xsd:decimal(?currentAllocationPct), "increased", "decreased") AS ?direction)
}
GROUP BY ?direction

